import os

import sys
import gradio as gr
import subscription_ui

# FADL AI PROJECT ROOT
PROJECT_ROOT = os.path.abspath(
    os.path.join(
        os.path.dirname(__file__),
        ".."
    )
)

if PROJECT_ROOT not in sys.path:
    sys.path.insert(0, PROJECT_ROOT)


QURAN_CODE_DIR = os.path.abspath(
    os.path.join(
        os.path.dirname(__file__),
        "..",
        "quran",
        "code"
    )
)
PRAYER_DIR = os.path.abspath(
    os.path.join(
        os.path.dirname(__file__),
        "..",
        "prayer"
    )
)
WUDU_DIR = os.path.abspath(
    os.path.join(
        os.path.dirname(__file__),
        "..",
        "wudu",
        "code"
    )
)
IMAGE_TO_VIDEO_DIR = os.path.abspath(
    os.path.join(
        os.path.dirname(__file__),
        "..",
        "image_to_video",
        "code"
    )
)
IMAGE_TO_VIDEO_LITE_DIR = os.path.abspath(
    os.path.join(
        os.path.dirname(__file__),
        "..",
        "image_to_video_lite",
        "code"
    )
)
TEXT_TO_VIDEO_DIR = os.path.abspath(
    os.path.join(
        os.path.dirname(__file__),
        "..",
        "text_to_video",
        "code"
    )
)

for path in [
    QURAN_CODE_DIR,
    PRAYER_DIR,
    WUDU_DIR,
    IMAGE_TO_VIDEO_DIR,
    IMAGE_TO_VIDEO_LITE_DIR,
    TEXT_TO_VIDEO_DIR
]:
    if path not in sys.path:
        sys.path.insert(0, path)

import quran_ui
import prayer_ui
import wudu_ui
import image_to_video_ui
import image_to_video_lite_ui
import text_to_video_ui


def create_main_app():

    welcome_css = """

    /* FADL AI — hide Gradio footer */
    footer {
        display: none !important;
    }

    .footer {
        display: none !important;
    }

    footer.svelte-1rjryqp {
        display: none !important;
    }


    body {
        direction: rtl;
    }

    .fadl-brand-banner {
        width: 100%;
        max-width: 1100px;
        margin: 0 auto 24px auto;
        border-radius: 24px;
        overflow: hidden;
        box-shadow:
            0 12px 30px rgba(0, 70, 55, 0.20);
        border: 1px solid rgba(202, 165, 75, 0.35);
    }

    .fadl-brand-banner img {
        width: 100%;
        display: block;
    }

    .fadl-home {
        max-width: 1100px;
        margin: 0 auto;
        text-align: center;
        direction: rtl;
    }

    .fadl-home-header {
        margin: 16px 0 28px 0;
    }

    .fadl-home-icon {
        width: 120px;
        height: 120px;
        border-radius: 28px;
        object-fit: cover;
        box-shadow:
            0 8px 24px rgba(0, 75, 58, 0.22);
        border: 2px solid rgba(212, 175, 55, 0.5);
        margin-bottom: 12px;
    }

    .fadl-home-title {
        font-size: 34px;
        font-weight: 800;
        color: #0d5b46;
        margin: 8px 0 4px 0;
    }

    .fadl-home-tagline {
        font-size: 19px;
        color: #9a7628;
        font-weight: 600;
        margin-bottom: 8px;
    }

    .fadl-home-subtitle {
        color: #59645f;
        font-size: 16px;
        margin-bottom: 26px;
    }

    .fadl-cards {
        display: grid;
        grid-template-columns:
            repeat(auto-fit, minmax(180px, 1fr));
        gap: 16px;
        margin-top: 12px;
    }

    .fadl-card-home {
        background:
            linear-gradient(
                145deg,
                #ffffff 0%,
                #f4faf7 100%
            );
        border: 1px solid rgba(16, 99, 75, 0.15);
        border-radius: 20px;
        padding: 22px 14px;
        box-shadow:
            0 6px 18px rgba(0, 68, 50, 0.08);
    }

    .fadl-card-home .emoji {
        font-size: 34px;
        margin-bottom: 10px;
    }

    .fadl-card-home h3 {
        margin: 0 0 6px 0;
        color: #0d5b46;
        font-size: 19px;
    }

    .fadl-card-home p {
        margin: 0;
        color: #6a746f;
        font-size: 14px;
    }


    .fadl-home {
        position: relative;
    }


    #fadl-welcome {
        position: fixed;
        inset: 0;
        z-index: 99999;
        background: linear-gradient(
            160deg,
            #ffffff 0%,
            #f5faf7 100%
        );
        display: flex;
        align-items: center;
        justify-content: center;
        text-align: center;
        direction: rtl;
        animation: fadlFadeOut 0.7s ease 2.3s forwards;
    }

    #fadl-welcome .fadl-card {
        animation: fadlWelcomeIn 0.8s ease;
    }

    #fadl-welcome .fadl-smile {
        font-size: 72px;
        display: block;
        margin-bottom: 12px;
        animation: fadlSmile 1.2s ease-in-out infinite;
    }

    #fadl-welcome h1 {
        font-size: 36px;
        margin: 8px 0;
    }

    #fadl-welcome h2 {
        font-size: 25px;
        margin: 8px 0;
        font-weight: 600;
    }

    #fadl-welcome p {
        font-size: 17px;
        opacity: 0.75;
        margin-top: 16px;
    }

    @keyframes fadlWelcomeIn {
        from {
            opacity: 0;
            transform: translateY(16px);
        }
        to {
            opacity: 1;
            transform: translateY(0);
        }
    }

    @keyframes fadlSmile {
        0%, 100% {
            transform: scale(1) rotate(0deg);
        }
        50% {
            transform: scale(1.08) rotate(4deg);
        }
    }

    @keyframes fadlFadeOut {
        from {

PROJECT_ROOT = os.path.abspath(
    os.path.join(
        os.path.dirname(__file__),
        ".."
    )
)

if PROJECT_ROOT not in sys.path:
    sys.path.insert(0, PROJECT_ROOT)

            opacity: 1;
            visibility: visible;
        }
        to {
            opacity: 0;
            visibility: hidden;
            pointer-events: none;
        }
    }
    """

    with gr.Blocks(
        title="فضل AI"
    ) as app:

        gr.HTML(
            """
            <div id="fadl-welcome">
                <div class="fadl-card">

                    <span class="fadl-smile">
                        😊
                    </span>

                    <h1>السلام عليكم</h1>

                    <h2>
                        أهلًا بيك في فضل AI
                    </h2>

                    <p>
                        ذكاء يساعدك بإبداع…
                        بقيم نحافظ عليها.
                    </p>

                </div>
            </div>
            """
        )


        with gr.Tabs():

            # الرئيسية
            with gr.Tab("الرئيسية"):

                gr.HTML(
                    """
                    <div class="fadl-home">


                        <div class="fadl-brand-banner">
                            <img
                                src="data:image/png;base64,"
                                alt="فضل AI"
                            />
                        </div>

                        <div class="fadl-home-header">

                            <img
                                class="fadl-home-icon"
                                src="data:image/png;base64,"
                                alt="أيقونة فضل AI"
                            />

                            <div class="fadl-home-title">
                                فضل AI
                            </div>

                            <div class="fadl-home-tagline">
                                ذكاء يُعينك على الخير
                            </div>

                            <div class="fadl-home-subtitle">
                                اختر القسم الذي تريد استخدامه
                            </div>

                        </div>

                        <div class="fadl-cards">

                            <div class="fadl-card-home">
                                <div class="emoji">📖</div>
                                <h3>القرآن الكريم</h3>
                                <p>قراءة وتلاوة وحماية للنص القرآني</p>
                            </div>

                            <div class="fadl-card-home">
                                <div class="emoji">🕌</div>
                                <h3>الصلاة</h3>
                                <p>تعليم الصلاة بالصوت والحركات</p>
                            </div>

                            <div class="fadl-card-home">
                                <div class="emoji">💧</div>
                                <h3>الوضوء</h3>
                                <p>الوضوء خطوة بخطوة</p>
                            </div>

                            <div class="fadl-card-home">
                                <div class="emoji">🎬</div>
                                <h3>صورة إلى فيديو</h3>
                                <p>تحريك الصور مع الحفاظ على الهوية</p>
                            </div>

                            <div class="fadl-card-home">
                                <div class="emoji">✨</div>
                                <h3>نص إلى فيديو</h3>
                                <p>حوّل وصفك إلى مشهد فيديو</p>
                            </div>

                        </div>
                    </div>
                    """
                )

            # القرآن
            with gr.Tab("القرآن الكريم"):

                surah_choices = [
                    f'{num} - {quran_ui.quran_db[str(num)]["name"]}'
                    for num in range(1, 115)
                ]

                gr.Markdown("## القرآن الكريم")

                surah_menu = gr.Dropdown(
                    choices=surah_choices,
                    value="1 - الفاتحة",
                    label="اختر السورة"
                )

                quran_button = gr.Button(
                    "عرض السورة وتشغيل التلاوة"
                )

                quran_text = gr.Textbox(
                    label="نص السورة",
                    lines=16,
                    interactive=False
                )

                quran_audio = gr.Audio(
                    label="التلاوة",
                    type="filepath",
                    autoplay=True
                )

                quran_button.click(
                    fn=quran_ui.prepare_surah,
                    inputs=surah_menu,
                    outputs=[
                        quran_text,
                        quran_audio
                    ]
                )

            # الصلاة
            with gr.Tab("الصلاة"):

                gr.Markdown(
                    "## الصلاة بالصوت والحركات"
                )

                gr.Markdown("### الأذان")
                gr.Video(
                    value=os.path.join(
                        PRAYER_DIR,
                        "adhan",
                        "adhan.mp4"
                    ),
                    label="فيديو الأذان"
                )

                gr.Markdown("### الإقامة")
                gr.Video(
                    value=os.path.join(
                        PRAYER_DIR,
                        "iqama",
                        "sadtalker_result",
                        "2026_08_18_04.48.33.mp4"
                    ),
                    label="فيديو الإقامة"
                )

                gr.Markdown("### الصلاة ركعتين")

                (
                    step_state,
                    counter,
                    action_box,
                    details_box,
                    image_box,
                    audio_box
                ) = prayer_ui.add_prayer_ui()

                app.load(
                    fn=lambda: prayer_ui.render_step(0),
                    inputs=[],
                    outputs=[
                        step_state,
                        counter,
                        action_box,
                        details_box,
                        image_box,
                            audio_box
                    ]
                )

            # الوضوء
            with gr.Tab("الوضوء"):

                gr.Markdown(
                    "## الوضوء خطوة بخطوة"
                )

                (
                    wudu_state,
                    wudu_counter,
                    wudu_name,
                    wudu_image
                ) = wudu_ui.add_wudu_ui()

                app.load(
                    fn=lambda: wudu_ui.render_step(0),
                    inputs=[],
                    outputs=[
                        wudu_state,
                        wudu_counter,
                        wudu_name,
                        wudu_image
                    ]
                )

            # صورة إلى فيديو
            with gr.Tab("صورة إلى فيديو"):
                image_to_video_ui.add_image_to_video_ui()

            # نص إلى فيديو
            with gr.Tab("نص إلى فيديو"):
                text_to_video_ui.add_text_to_video_ui()


            # الاشتراك
            with gr.Tab("💎 الاشتراك"):
                subscription_balance_box = subscription_ui.add_subscription_ui()

        app.load(
            fn=subscription_ui._show_user_balance,
            inputs=None,
            outputs=subscription_balance_box,
        )

    app.fadl_welcome_css = welcome_css
    return app


if __name__ == "__main__":
    app = create_main_app()
    app.launch(
    css=app.fadl_welcome_css,
    share=True,
    allowed_paths=[
        "/content/fadl_ai"
    ]
)
